@spec tv_fx_patch_spec  src=tests/specs/tv_fx_patch_spec.lua  loc=189  cases=14
@exercises dataStore (h.ds), trackerManager (h.tm), configManager (h.cm), trackerView (h.vm)
@surface   ds:assign, tm:rebuild, cm:getAt, vm:saveFxPatch, vm:setFxField, tm:subscribe, vm:loadFxPatch, vm:noteFx, vm:publishFxPatch, vm:deleteFxPatch
@harness   mk

# Intent
  Pin-tests for the fx patch catalogue: `tv:saveFxPatch` stamps the caret host's
  chain into the project tier of `fxPatches` -- verbatim, by copy, and without
  costing a re-derivation; `tv:loadFxPatch` copies a named chain back out onto a
  host, replacing what it held. see design/note-macros-v2.md § The chain surface

# Helpers
  @fn injectRegion(h, fx)  @ 13-16
  @fn projectPatches(h)  @ 18
  @fn libraryPatches(h)  @ 19
  @fn withCatalogue(harness, project, library)  @ 26-31
      -- A region carrying `chain`, with the catalogue's two tiers seeded around it.

# Cases
  @case 'save stamps the host chain into the project tier, verbatim'  [harness]  @ 35-41
  @case 'the catalogue holds a copy, not a live handle on the chain'  [harness]  @ 45-52
  @case 'saving re-realises nothing'  [harness]  @ 56-64
  @case 'a host with no chain saves nothing'  [harness]  @ 68-74
  @case 'the load replaces the host chain rather than appending to it'  [harness]  @ 80-85
  @case 'the host holds a copy, not a live handle on the catalogue'  [harness]  @ 89-95
  @case 'bypass rides the patch onto the host'  [harness]  @ 99-105
  @case 'project resolves over library, and a library-only name still loads'  [harness]  @ 109-116
  @case 'a name in neither tier loads nothing'  [harness]  @ 120-125
  @case 'publish lifts the project body into the library tier, leaving the project copy standing'  [harness]  @ 131-138
  @case 'deleting a project row leaves the library copy it shadowed standing'  [harness]  @ 142-151
  @case 'deleting a library row takes the name out of the catalogue outright'  [harness]  @ 155-162
  @case 'neither gesture re-realises anything'  [harness]  @ 166-175
  @case 'the whole list lands in one write'  [harness]  @ 179-187

